import { Component } from "@angular/core";
import { CommonModule } from "@angular/common";

type Project = {
  title: string;
  desc: string;
  tech: string[];
  live: string;
  github?: string;
  image?: string;
};

@Component({
  selector: "app-projects",
  standalone: true,
  imports: [CommonModule],
  templateUrl: "./projects.component.html",
  styleUrls: ["./projects.component.css"],
})
export class ProjectsComponent {
  readonly projects: Project[] = [
    {
      title: "MERN Authentication System",
      desc: "Secure authentication app with user registration, login, and protected routes built with the MERN stack.",
      tech: ["MongoDB", "Express", "React", "Node.js"],
      live: "https://mern-authentication-system-eight.vercel.app",
    },
    {
      title: "MERN CRUD App",
      desc: "Full-stack CRUD application for creating, reading, updating, and deleting data with a responsive UI.",
      tech: ["MongoDB", "Express", "React", "Node.js"],
      live: "https://mern-crud-taupe.vercel.app",
    },
  ];
}
<section id="projects" class="projects">
  <div class="container projects-container">
    <h2>Projects</h2>

    <div class="projects-grid">
      <div class="project-card" *ngFor="let project of projects">
        <div class="project-image project-placeholder">
          <span>{{ project.title }}</span>
        </div>

        <h3>{{ project.title }}</h3>

        <p>{{ project.desc }}</p>

        <div class="tech">
          <span class="tech-tag" *ngFor="let item of project.tech">
            {{ item }}
          </span>
        </div>

        <div class="project-links">
          <a href="{{ project.live }}" target="_blank" rel="noreferrer">Live</a>
          <a
            *ngIf="project.github"
            href="{{ project.github }}"
            target="_blank"
            rel="noreferrer"
            >GitHub</a
          >
        </div>
      </div>
    </div>
  </div>
</section>
